<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {Sparkles,Square,ArrowRight,SlidersHorizontal,History} from 'lucide-vue-next'
import {parseWritingProse} from './prose'
import Sheet from '../components/Sheet.vue'
import DirectionsPanel from './DirectionsPanel.vue'
import EventLedgerPanel from './EventLedgerPanel.vue'
