const props=defineProps<{storyId:string;branchId:string|null;anchor:ProgressAnchor|null;open:boolean;returnTo?:'stage';intentId?:string;sourceRevision?:number;readOnly?:boolean}>(),emit=defineEmits<{close:[]}>(),store=useLocal(),route=useRoute(),router=useRouter()
const count=ref(1),custom=ref(false),direction=ref(''),once=ref<Partial<WritingPreferences>>({}),selectedPlanId=ref<string|null>(null),global=ref<Document<WritingPreferenceLayer>|null>(null),book=ref<Document<WritingPreferenceLayer>|null>(null),scope=ref<'global'|'book'|'once'>('once'),hydrating=ref(false),pending=ref(0),draftDurable=ref(''),planPending=ref(false),directionsPanel=ref<InstanceType<typeof DirectionsPanel>|null>(null)
const draftId=ref(''),draftCreatedAt=ref<string|undefined>(),drafts=ref<Document<WritingComposeDraft>[]>([])
const advanced=ref(false),busy=ref(false),saving=ref(false),error=ref(''),preview=ref(''),model=ref<Document<ProviderConfiguration>|null>(null),runs=ref<Document<WritingRun>[]>([]),selectedId=ref(typeof route.query.task==='string'?route.query.task:''),inspection=ref<Awaited<ReturnType<typeof previewWritingRequest>>|null>(null),inspectBusy=ref(false)
const resolved=computed(()=>resolveWritingPreferences(global.value?.value.values,book.value?.value.values,once.value)),capabilityWarnings=computed(()=>model.value?writingCapabilityWarnings(resolved.value.values,model.value.value.outputLimit):[]),fieldLabels:Record<WritingPreferenceField,string>={length:'每章目标字数',style:'风格',forbidden:'禁词',authorNote:'作者注释',template:'写作模板'}
const current=computed(()=>runs.value.find(row=>row.id===selectedId.value)||null),prefix=computed(()=>current.value?completePrefix(current.value.value):0),inFlight=computed(()=>current.value?.value.status==='running'),labels={queued:'待开始',running:'正在写',completed:'已完成',failed:'写作中断',cancelled:'已停止',unknown:'请求待核对'},chapterLabels={queued:'待写',running:'正在写',complete:'完整章节',partial:'已收到片段',failed:'未完成',unknown:'请求待核对'}
const usageLabel=(field:'input'|'output')=>{const chapters=current.value?.value.chapters.filter(c=>c.attemptId)||[],known=chapters.filter(c=>c.usage[field]!==null),unknown=chapters.length-known.length;return known.length?known.reduce((n,c)=>n+c.usage[field]!,0)+(unknown?' + '+unknown+' 章未知':''):'未知'}
const chapterProse=(chapter:WritingRun['chapters'][number])=>chapter.raw===undefined?parseWritingProse(chapter.text).text:chapter.text
const fullRecord=ref(false),shownChapters=computed(()=>{const run=current.value?.value;if(!run)return [];return (run.targetBranchId===props.branchId&&!fullRecord.value?run.chapters.slice(run.acceptedCount):run.chapters).filter(c=>c.status!=='queued')})
let disposed=false,poll:ReturnType<typeof setInterval>|null=null,epoch=0,reloadEpoch=0,work=Promise.resolve()
const draftStates=new Map<string,{revision:number;durable:string}>(),layerStates=new Map<string,{revision:number;durable:string}>()
const compose=():WritingComposeDraft=>({assetType:'writing-compose-draft',storyId:props.storyId,count:count.value,direction:direction.value,once:JSON.parse(canonical(once.value)),selectedPlanId:selectedPlanId.value,...(draftCreatedAt.value?{createdAt:draftCreatedAt.value}:{})})
const composeDirty=computed(()=>canonical(compose())!==draftDurable.value)
function showDraft(row:Document<WritingComposeDraft>){hydrating.value=true;draftId.value=row.id;draftCreatedAt.value=row.value.createdAt;count.value=row.value.count;direction.value=row.value.direction;once.value=row.value.once;selectedPlanId.value=row.value.selectedPlanId;custom.value=![1,3,5].includes(count.value);draftDurable.value=canonical(compose());draftStates.set(row.id,{revision:row.revision,durable:draftDurable.value});const index=drafts.value.findIndex(d=>d.id===row.id);if(index<0)drafts.value.unshift(row);else drafts.value[index]=row;hydrating.value=false}
const layerDirty=computed(()=>{pending.value;return [global.value,book.value].some(row=>row&&canonical(row.value.values)!==(layerStates.get(row.id)?.durable||'{}'))}),draftSaved=computed(()=>pending.value===0&&canonical(compose())===draftDurable.value&&!planPending.value&&!layerDirty.value)
function show(row:Document<WritingRun>,focus=false){if(disposed||!store.vault?.unlocked)return;const index=runs.value.findIndex(item=>item.id===row.id);if(index<0)runs.value.unshift(row);else runs.value[index]=row;if(focus||!selectedId.value)selectedId.value=row.id}
async function load(){const vault=store.vault,ticket=++reloadEpoch;if(!vault)return;const rows=(await vault.list<WritingRun>('settings')).filter(row=>row.value.assetType==='writing-run'&&!row.value.purpose&&row.value.storyId===props.storyId&&(props.sourceRevision===undefined?(row.value.parentBranchId===props.branchId||row.value.acceptedCount>0&&row.value.targetBranchId===props.branchId):(row.value.parentBranchId===props.branchId&&row.value.parentRevision===props.sourceRevision&&canonical(row.value.anchor)===canonical(props.anchor)))).sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));if(disposed||ticket!==reloadEpoch||store.vault!==vault)return;runs.value=rows.map(row=>writingPendingView(vault,row));if(!selectedId.value&&rows.length)selectedId.value=rows[0]!.id;for(const row of rows)if(row.value.status==='running'){const recovered=await recoverWriting(vault,row);if(disposed||ticket!==reloadEpoch)return;const index=runs.value.findIndex(item=>item.id===row.id);if(index>=0)runs.value[index]=recovered}}
function changed(event:Event){const detail=(event as CustomEvent<{vaultId:string}>).detail;if(detail?.vaultId===store.vault?.id&&!busy.value)void load().catch(()=>{})}
function saveDraft(){const vault=store.vault,id=draftId.value;if(!vault||hydrating.value||disposed||!draftStates.has(id))return work;const value=compose(),signature=canonical(value),state=draftStates.get(id)!;pending.value++;const job=work.catch(()=>{}).then(async()=>{if(signature===state.durable)return;const saved=await saveWritingComposeDraft(vault,state.revision,value,id);state.revision=saved.revision;state.durable=signature;if(!disposed&&store.vault===vault&&draftId.value===id){draftDurable.value=signature;const index=drafts.value.findIndex(d=>d.id===id);if(index<0)drafts.value.unshift(saved);else drafts.value[index]=saved}});work=job.finally(()=>pending.value--);void work.catch(e=>{if(!disposed)error.value=(e as Error).message});return work}
async function copyCompose(){const vault=store.vault,ticket=epoch;if(!vault||busy.value)return;try{await work.catch(()=>{});const value={...compose(),createdAt:new Date().toISOString()},row=await saveWritingComposeDraft(vault,0,value,'writing-compose-copy:'+crypto.randomUUID());if(disposed||ticket!==epoch||store.vault!==vault)return;showDraft(row);work=Promise.resolve();await saveWritingComposeView(vault,props.storyId,row.id);error.value=''}catch(e){if(!disposed)error.value=(e as Error).message}}
async function chooseDraft(id:string){const vault=store.vault,ticket=epoch;if(!vault||busy.value)return;try{await flush();const row=await vault.read<WritingComposeDraft>(id);if(disposed||ticket!==epoch||store.vault!==vault||row?.value.storyId!==props.storyId)return;showDraft(row);await saveWritingComposeView(vault,props.storyId,row.id);error.value=''}catch(e){if(!disposed)error.value=(e as Error).message}}
watch([count,direction,once,selectedPlanId],()=>{inspection.value=null;if(!hydrating.value)void saveDraft()},{deep:true,flush:'sync'})
function layerValues(){return scope.value==='once'?once.value:(scope.value==='global'?global.value:book.value)?.value.values||{}}
function hasOverride(field:WritingPreferenceField){return Object.hasOwn(layerValues(),field)}
function preferenceValue(field:WritingPreferenceField){const inherited=scope.value==='global'?writingDefaults:scope.value==='book'?resolveWritingPreferences(global.value?.value.values).values:resolved.value.values;return layerValues()[field]??inherited[field]}
function changePreference(field:WritingPreferenceField,value:string|number|undefined){const target=scope.value,values={...layerValues()};if(value===undefined)delete values[field];else(values as Record<string,unknown>)[field]=value;if(target==='once'){once.value=values;return}const vault=store.vault,storyId=props.storyId;if(!vault)return;const id=target==='global'?'settings:writing:global':'settings:writing:book:'+storyId,state=layerStates.get(id)||{revision:0,durable:'{}'};layerStates.set(id,state);const display={id,kind:'settings' as const,revision:state.revision,updatedAt:new Date().toISOString(),value:{assetType:'writing-preferences' as const,scope:target,storyId:target==='global'?null:storyId,values}};if(target==='global')global.value=display;else book.value=display;inspection.value=null;pending.value++;const signature=canonical(values),job=work.catch(()=>{}).then(async()=>{if(signature===state.durable)return;const row=await saveWritingPreferenceLayer(vault,target,storyId,state.revision,values);state.revision=row.revision;state.durable=signature;if(!disposed&&store.vault===vault&&props.storyId===storyId){const shown=target==='global'?global.value:book.value;if(shown)shown.revision=row.revision}});work=job.finally(()=>pending.value--);void work.catch(e=>{if(!disposed)error.value=(e as Error).message})}
async function flush(){await directionsPanel.value?.flush();await saveDraft();await work;if(layerDirty.value||canonical(compose())!==draftDurable.value)throw new Error('输入尚未保存，原设置保留。可另存为本次设置。')}
async function preserveSettings(){const vault=store.vault;if(!vault)return;try{await work.catch(()=>{});const retained={...global.value?.value.values,...book.value?.value.values,...once.value};once.value=retained;await saveDraft();await work;const layers=await writingPreferenceLayers(vault,props.storyId);global.value=layers.global;book.value=layers.book;for(const target of ['global','book'] as const){const row=layers[target];layerStates.set(target==='global'?'settings:writing:global':'settings:writing:book:'+props.storyId,{revision:row?.revision||0,durable:canonical(row?.value.values||{})})}scope.value='once';error.value=''}catch(e){error.value=(e as Error).message}}
watch(()=>props.open,async open=>{if(!open)return;const ticket=++epoch,vault=store.vault,anchor=props.anchor;if(!vault||!anchor)return;error.value='';hydrating.value=true;draftId.value='settings:writing-draft:'+props.storyId;draftCreatedAt.value=undefined;drafts.value=[];count.value=1;custom.value=false;direction.value='';once.value={};selectedPlanId.value=null;scope.value='once';global.value=null;book.value=null;inspection.value=null;model.value=null;try{await work;const [paragraph,profile,layers,baseDraft,legacy,allSettings,view]=await Promise.all([vault.read<Paragraph>(anchor.paragraphId),slotModel(vault,'text').catch(()=>null),writingPreferenceLayers(vault,props.storyId),vault.read<WritingComposeDraft>('settings:writing-draft:'+props.storyId),vault.read<{count:number;direction:string;length:number;style:string;forbidden:string;authorNote:string}>('settings:writing:'+props.storyId),vault.list<WritingComposeDraft>('settings'),vault.read<WritingComposeView>('settings:writing-compose-view:'+props.storyId)]);if(disposed||ticket!==epoch||!props.open||store.vault!==vault)return;preview.value=paragraph?.value.text.slice(Math.max(0,anchor.offset-160),anchor.offset)||'本段开始之前';model.value=profile;global.value=layers.global;book.value=layers.book;for(const target of ['global','book'] as const){const row=layers[target];layerStates.set(target==='global'?'settings:writing:global':'settings:writing:book:'+props.storyId,{revision:row?.revision||0,durable:canonical(row?.value.values||{})})}drafts.value=allSettings.filter(r=>r.value.assetType==='writing-compose-draft'&&r.value.storyId===props.storyId).sort((a,b)=>(b.value.createdAt||b.updatedAt).localeCompare(a.value.createdAt||a.updatedAt));const draft=drafts.value.find(d=>d.id===view?.value.draftId)||baseDraft;if(draft){draftId.value=draft.id;draftCreatedAt.value=draft.value.createdAt;count.value=draft.value.count;direction.value=draft.value.direction;once.value=draft.value.once;selectedPlanId.value=draft.value.selectedPlanId}else if(legacy){count.value=legacy.value.count;direction.value=legacy.value.direction;once.value={length:legacy.value.length,style:legacy.value.style,forbidden:legacy.value.forbidden,authorNote:legacy.value.authorNote}}custom.value=![1,3,5].includes(count.value);draftDurable.value=canonical(compose());draftStates.set(draftId.value,{revision:draft?.revision||0,durable:draftDurable.value})}catch(e){if(ticket===epoch)error.value=(e as Error).message}finally{if(ticket===epoch)hydrating.value=false}},{immediate:true})
async function inspect(){const vault=store.vault,anchor=props.anchor,ticket=epoch;if(!vault||!anchor||inspectBusy.value)return;inspectBusy.value=true;try{await flush();const result=await previewWritingRequest(vault,await slotModel(vault,'text'),anchor,{chapterCount:count.value,direction:direction.value,...once.value,...(props.sourceRevision===undefined?{}:{sourceRevision:props.sourceRevision})});if(!disposed&&ticket===epoch&&store.vault===vault)inspection.value=result}catch(e){if(!disposed)error.value=(e as Error).message}finally{inspectBusy.value=false}}
async function start(){const vault=store.vault,anchor=props.anchor;if(!vault||!anchor||busy.value||props.readOnly)return;busy.value=true;error.value='';try{await flush();const options={chapterCount:count.value,direction:direction.value,...once.value,...(props.sourceRevision===undefined?{}:{sourceRevision:props.sourceRevision}),...(props.intentId?{intentId:props.intentId}:{})},profile=await slotModel(vault,'text');if(disposed||store.vault!==vault||!vault.unlocked)return;model.value=profile;const row=await prepareWriting(vault,profile,anchor,options);show(row,true);if(!disposed){emit('close');await nextTick();if(!disposed)document.getElementById('local-writing-output')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}if(row.value.status==='queued')await new LocalWritingExecution(vault,row.id,show).execute()}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function accept(){const vault=store.vault,row=current.value;if(!vault||!row||saving.value||props.readOnly)return;saving.value=true;error.value='';try{const result=await acceptWriting(vault,row.id,prefix.value);if(disposed||store.vault!==vault||!vault.unlocked||selectedId.value!==row.id)return;await load();if(disposed||store.vault!==vault||!vault.unlocked||selectedId.value!==row.id)return;const accepted=runs.value.find(run=>run.id===row.id);await router.push({path:(props.returnTo==='stage'?'/local/stage/':'/local/read/')+props.storyId,query:{branch:result.branchId,paragraph:accepted?.value.chapters[row.value.acceptedCount]?.paragraphIds[0]||undefined}})}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)saving.value=false}}
async function retrySave(){const vault=store.vault,row=current.value;if(!vault||!row||saving.value)return;saving.value=true;try{show(await retryWritingSave(vault,row.id));error.value=''}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function stop(){const vault=store.vault,row=current.value;if(vault&&row)try{await stopWriting(vault,row.id)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function close(){if(busy.value)return;try{await flush();epoch++;emit('close')}catch(e){error.value=(e as Error).message}}
function beforeUnload(event:BeforeUnloadEvent){if(props.open&&!draftSaved.value){event.preventDefault();event.returnValue=''}}
async function canLeave(){if(!props.open)return true;try{await flush();epoch++;return true}catch(e){error.value=(e as Error).message;return false}}
onBeforeRouteLeave(canLeave)
onBeforeRouteUpdate(canLeave)
onMounted(()=>{void load().catch(e=>error.value=(e as Error).message);poll=setInterval(()=>{if(!busy.value)void load().catch(()=>{})},2000);window.addEventListener('reader-local-writing-changed',changed);window.addEventListener('beforeunload',beforeUnload)})
onUnmounted(()=>{disposed=true;epoch++;reloadEpoch++;if(poll)clearInterval(poll);window.removeEventListener('reader-local-writing-changed',changed);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
  <section v-if="current" id="local-writing-output" class="final-writing-output" aria-label="写作正文">
    <div class="final-writing-toolbar"><span role="status"><Sparkles :size="16"/>{{labels[current.value.status]}}</span><button v-if="inFlight" aria-label="停止写作" @click="stop"><Square :size="15"/>停止</button><details v-if="runs.length"><summary><History :size="16"/>写作记录</summary><select v-model="selectedId" aria-label="选择写作记录"><option v-for="row in runs" :key="row.id" :value="row.id">{{new Date(row.value.createdAt).toLocaleString()}} · {{labels[row.value.status]}}</option></select></details></div>
    <div v-for="chapter in shownChapters" :key="chapter.id" class="final-writing-chapter"><h2>{{chapter.title}}</h2><small v-if="chapter.status!=='complete'" class="final-subtle">{{chapterLabels[chapter.status]}}</small><div class="final-writing-prose">{{chapterProse(chapter)||'正在等待正文…'}}</div><EventLedgerPanel v-if="chapter.eventLedger" :ledger="chapter.eventLedger"/><details v-if="chapter.raw||chapter.text!==chapterProse(chapter)" class="final-writing-details"><summary>原返回</summary><pre>{{chapter.raw??chapter.text}}</pre></details><details v-if="chapter.warnings.length" class="final-writing-warning"><summary>本章提示 · {{chapter.warnings.length}}</summary><p v-for="warning in chapter.warnings" :key="warning">{{warning}}</p></details></div>
    <AcceptedBasisPanel v-if="current.value.acceptedBasis" :basis="current.value.acceptedBasis"/>
    <label v-if="current.value.targetBranchId===branchId&&current.value.acceptedCount" class="final-check final-writing-details"><input v-model="fullRecord" type="checkbox">查看本次全部正文</label>
    <p v-if="current.value.error" class="final-writing-warning" role="status">{{current.value.error}}</p><p v-if="error&&!open" class="final-error" role="alert">{{error}}</p>
    <div class="final-writing-controls"><button v-if="prefix>current.value.acceptedCount" class="final-primary" :disabled="saving||readOnly" @click="accept">接受 {{prefix}} 章并阅读<ArrowRight :size="16"/></button><RouterLink v-else-if="current.value.acceptedCount" class="final-text-link" :to="{path:'/local/read/'+storyId,query:{branch:current.value.targetBranchId}}">阅读这条故事线<ArrowRight :size="16"/></RouterLink><button v-if="store.vault&&hasPendingWritingSave(store.vault,current.id)" :disabled="saving" @click="retrySave">只重试保存</button></div>
    <details class="final-writing-details"><summary>模型与用量</summary><p>{{current.value.configSnapshot.modelId}} · 最多 {{current.value.chapterCount}} 次</p><p>已发 {{current.value.chapters.filter(c=>c.attemptId).length}} 次 · 输入 {{usageLabel('input')}} · 输出 {{usageLabel('output')}}</p><p>{{current.value.append?'接入当前故事线':'保存到新故事线'}}</p></details>
  </section>
  <Sheet v-if="open" title="从这里写" @close="close"><form class="final-writing-form" @submit.prevent="start"><fieldset :disabled="busy||hydrating||readOnly"><label v-if="drafts.length>1">输入记录<select aria-label="选择写作输入" :value="draftId" @change="chooseDraft(($event.target as HTMLSelectElement).value)"><option v-for="draft in drafts" :key="draft.id" :value="draft.id">{{draft.id.startsWith('writing-compose-copy:')?'副本':'原输入'}} · {{draft.value.count}} 章 · {{draft.value.direction.slice(0,14)||'自然接着写'}}</option></select></label><blockquote>{{preview}}</blockquote><h3>接下来，写几章？</h3><div class="final-writing-count"><button v-for="number in [1,3,5]" :key="number" type="button" :aria-pressed="!custom&&count===number" @click="custom=false;count=number">{{number}} 章</button><button type="button" :aria-pressed="custom" @click="custom=true">自定义</button></div><label v-if="custom">章数<input v-model.number="count" type="number" min="1" max="10" required></label><label>故事走向 <small>选填</small><textarea v-model="direction" aria-label="故事走向" maxlength="20000" rows="4" placeholder="留空，接着故事自然写下去"/></label><small role="status">{{draftSaved?'写作草稿已保存':'正在保存输入…'}}</small><DirectionsPanel v-if="sourceRevision===undefined" ref="directionsPanel" :story-id="storyId" :anchor="anchor" :direction="direction" :once="once" :selected-plan-id="selectedPlanId" :disabled="busy||hydrating" @view="selectedPlanId=$event" @choose="direction=$event.direction;selectedPlanId=$event.id" @pending="planPending=$event"/><div class="final-writing-meta"><RouterLink to="/local/settings/models">{{model?.value.modelId||'选择文本模型'}}</RouterLink><button type="button" @click="advanced=!advanced"><SlidersHorizontal :size="16"/>设置</button></div><div v-if="advanced" class="final-writing-advanced"><label>设置范围<select v-model="scope" aria-label="写作设置范围"><option value="once">本次</option><option value="book">本书</option><option value="global">全局</option></select></label><div v-for="field in writingPreferenceFields" :key="field" class="final-preference-field"><label class="final-check"><input type="checkbox" :checked="hasOverride(field)" :aria-label="'覆盖'+fieldLabels[field]" @change="changePreference(field,($event.target as HTMLInputElement).checked?preferenceValue(field):undefined)">{{fieldLabels[field]}}<small>{{preferenceScopeLabels[resolved.sources[field]]}}</small></label><input v-if="field==='length'" :value="preferenceValue(field)" type="number" min="100" max="10000" :disabled="!hasOverride(field)" :aria-label="fieldLabels[field]" @input="changePreference(field,Number(($event.target as HTMLInputElement).value))"><textarea v-else :value="preferenceValue(field)" :disabled="!hasOverride(field)" :aria-label="fieldLabels[field]" :maxlength="field==='template'||field==='authorNote'?20000:10000" :rows="field==='template'?4:2" @input="changePreference(field,($event.target as HTMLTextAreaElement).value)"/></div><details><summary>模板变量</summary><code v-pre>{{chapterTitle}} · {{direction}} · {{length}} · {{style}} · {{forbidden}} · {{authorNote}}</code></details><p v-for="warning in capabilityWarnings" :key="warning" class="final-writing-warning">{{warning}}</p><button type="button" :disabled="inspectBusy||!model" @click="inspect">预览实际请求</button><details v-if="inspection" open class="final-request-preview"><summary>请求预览 · {{inspection.modelId}}</summary><table><tbody><tr v-for="field in writingPreferenceFields" :key="field"><th>{{fieldLabels[field]}}</th><td>{{inspection.values[field]||'留空'}}</td><td>{{preferenceScopeLabels[inspection.sources[field]]}}</td></tr></tbody></table><small>输入估算 {{inspection.inputEstimate}} · 输出上限 {{inspection.outputLimit}} · 窗口 {{inspection.contextLimit}}</small><details><summary>发送的提示词</summary><article v-for="(message,index) in inspection.request" :key="index"><strong>{{message.role}}</strong><pre>{{message.content}}</pre></article></details></details></div><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="error&&composeDirty" type="button" @click="copyCompose">另存写作输入</button><button v-if="error&&layerDirty" type="button" @click="preserveSettings">另存为本次设置</button><button class="final-primary" :disabled="busy||!model||hydrating"><Sparkles :size="18"/>开始写作<span>{{count}} 章</span></button></fieldset></form></Sheet>

